example:
module "rule" {
  source              = "git::https://github.com/lace-cloud/registry-tf.git//modules/aws/eventbridge/rule?ref=v1.0.0"
  name                = "daily-cleanup"
  schedule_expression = "rate(1 day)"
  targets = [
    {
      arn = "arn:aws:lambda:us-east-1:123456789:function:cleanup"
    }
  ]
}

main_tf:
resource "aws_cloudwatch_event_rule" "this" {
  name                = var.name
  description         = var.description
  schedule_expression = var.schedule_expression
  event_pattern       = var.event_pattern
  state               = var.state
  event_bus_name      = var.event_bus_name

  tags = merge(
    {
      Name = var.name
    },
    var.tags
  )
}

resource "aws_cloudwatch_event_target" "this" {
  for_each = { for idx, target in var.targets : idx => target }

  rule           = aws_cloudwatch_event_rule.this.name
  arn            = each.value.arn
  target_id      = lookup(each.value, "target_id", null)
  input          = lookup(each.value, "input", null)
  input_path     = lookup(each.value, "input_path", null)
  role_arn       = lookup(each.value, "role_arn", null)
  event_bus_name = var.event_bus_name
}

outputs_tf:
output "rule_arn" {
  description = "ARN of the EventBridge rule"
  value       = aws_cloudwatch_event_rule.this.arn
}

output "rule_name" {
  description = "Name of the EventBridge rule"
  value       = aws_cloudwatch_event_rule.this.name
}

variables_tf:
variable "name" {
  description = "Name of the EventBridge rule"
  type        = string
}

variable "description" {
  description = "Description of the rule"
  type        = string
  default     = ""
}

variable "schedule_expression" {
  description = "Schedule expression (e.g., rate(1 hour), cron(0 12 * * ? *))"
  type        = string
  default     = null
}

variable "event_pattern" {
  description = "Event pattern JSON string"
  type        = string
  default     = null
}

variable "state" {
  description = "State of the rule (ENABLED or DISABLED)"
  type        = string
  default     = "ENABLED"
}

variable "event_bus_name" {
  description = "Event bus name (default for the default bus)"
  type        = string
  default     = "default"
}

variable "targets" {
  description = "List of targets for the rule"
  type = list(object({
    arn        = string
    target_id  = optional(string)
    input      = optional(string)
    input_path = optional(string)
    role_arn   = optional(string)
  }))
  default = []
}

variable "tags" {
  description = "Additional tags"
  type        = map(string)
  default     = {}
}

versions_tf:
terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}
